59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        // Normalize the address up front so every downstream use (the required-field check,
115	        // household-duplicate detection, the shared household id and the stored/returned value)
116	        // works from the same canonical form.
117	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
118	        List<String> missingFields = new ArrayList<>();
119	        if (isBlank(ownerFieldsDto.getFirstName())) {
120	            missingFields.add("firstName");
121	        }
122	        if (isBlank(ownerFieldsDto.getLastName())) {
123	            missingFields.add("lastName");
124	        }
125	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
126	        if (isBlank(normalizedAddress)) {
127	            missingFields.add("address");
128	        }
129	        if (isBlank(ownerFieldsDto.getCity())) {
130	            missingFields.add("city");
131	        }
132	        if (isBlank(ownerFieldsDto.getTelephone())) {
133	            missingFields.add("telephone");
134	        }
135	        if (!missingFields.isEmpty()) {
136	            throw new InvalidOwnerFieldsException(missingFields);
137	        }
138	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
139	        // already carry today's registration date, no further owners may be created today.
140	        LocalDate today = LocalDate.now();
141	        if (countOwnersRegisteredOn(today) >= MAX_OWNERS_PER_DAY) {
142	            throw new DailyOwnerLimitExceededException(today);
143	        }
144	        // Reject the request when the owner's city is already full: a city that already holds the
145	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
146	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
147	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
148	        }
149	        // Normalize the telephone into E.164 form; a number that cannot form a valid
150	        // E.164 value is rejected with a 400.
151	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
152	        // Email is optional; when present it must be a syntactically valid address and is
153	        // stored lower-cased. An invalid address is rejected with a 400.
154	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
155	        // Reject the request if the E.164 telephone is already used by any other owner.
156	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getTelephone)
158	            .filter(existing -> existing != null)
159	            .anyMatch(normalizedTelephone::equals);
160	        if (telephoneInUse) {
161	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
162	        }
163	        // Household handling for a matching last name + address (compared case-insensitively with
164	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
165	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
166	        // household and every member (the new owner and any existing ones) is stamped with the same
167	        // stable 'householdId'.
168	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
169	        String householdId = null;
170	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
171	            householdId = householdId(normalizedLastName, normalizedAddress);
172	            // Backfill the shared identifier onto any existing member of this household so the whole
173	            // household carries the same stable value.
174	            for (Owner existing : this.clinicService.findAllOwners()) {
175	                if (collapse(existing.getLastName()).equals(normalizedLastName)
176	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
177	                    && !householdId.equals(existing.getHouseholdId())) {
178	                    existing.setHouseholdId(householdId);
179	                    this.clinicService.saveOwner(existing);
180	                }
181	            }
182	        } else {
183	            boolean householdInUse = this.clinicService.findAllOwners().stream()
184	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
185	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
186	            if (householdInUse) {
187	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
188	            }
189	        }
190	        HttpHeaders headers = new HttpHeaders();
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	        owner.setAddress(normalizedAddress);
193	        owner.setTelephone(normalizedTelephone);
194	        owner.setEmail(normalizedEmail);
195	        owner.setHouseholdId(householdId);
196	        // Record how many existing owners (before this create) share this owner's first and last
197	        // name, compared case-insensitively. Computed against the current owners so the new owner
198	        // itself is never counted.
199	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
200	        // When no registration date is supplied, default it to the server's current date.
201	        if (owner.getRegistrationDate() == null) {
202	            owner.setRegistrationDate(LocalDate.now());
203	        }
204	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
205	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
206	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
207	        // owners already in that city.
208	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
209	        this.clinicService.saveOwner(owner);
210	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
219	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
220	        if (currentOwner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        currentOwner.setAddress(ownerFieldsDto.getAddress());
224	        currentOwner.setCity(ownerFieldsDto.getCity());
225	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
226	        currentOwner.setLastName(ownerFieldsDto.getLastName());
227	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
228	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
229	        this.clinicService.saveOwner(currentOwner);
230	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Transactional
235	    @Override
236	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        this.clinicService.deleteOwner(owner);
242	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        HttpHeaders headers = new HttpHeaders();
253	        Pet pet = petMapper.toPet(petFieldsDto);
254	        owner.setId(ownerId);
255	        pet.setOwner(owner);
256	        pet.getType().setName(null);
257	        this.clinicService.savePet(pet);
258	        PetDto petDto = petMapper.toPetDto(pet);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
260	            .buildAndExpand(pet.getId()).toUri());
261	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner != null) {
269	            Pet currentPet = this.clinicService.findPetById(petId);
270	            if (currentPet != null) {
271	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
272	                currentPet.setName(petFieldsDto.getName());
273	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
274	                this.clinicService.savePet(currentPet);
275	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
276	            }
277	        }
278	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
284	        HttpHeaders headers = new HttpHeaders();
285	        Visit visit = visitMapper.toVisit(visitFieldsDto);
286	        Pet pet = new Pet();
287	        pet.setId(petId);
288	        visit.setPet(pet);
289	        this.clinicService.saveVisit(visit);
290	        VisitDto visitDto = visitMapper.toVisitDto(visit);
291	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
292	            .buildAndExpand(visit.getId()).toUri());
293	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
294	    }
295	
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Override
299	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
300	        Owner owner = this.clinicService.findOwnerById(ownerId);
301	        if (owner != null) {
302	            Pet pet = owner.getPet(petId);
303	            if (pet != null) {
304	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
305	            }
306	        }
307	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	    }
309	
310	    private static boolean isBlank(String value) {
311	        return value == null || value.trim().isEmpty();
312	    }
313	
314	    /**
315	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
316	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
317	     * compared case-insensitively with collapsed whitespace.
318	     */
319	    private static String collapse(String value) {
320	        if (value == null) {
321	            return "";
322	        }
323	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
324	    }
325	
326	    /**
327	     * Common street-type abbreviations expanded during address normalization.
328	     */
329	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
330	        "ST", "STREET",
331	        "RD", "ROAD",
332	        "AVE", "AVENUE");
333	
334	    /**
335	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
336	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
337	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
338	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
339	     * address maps to itself.
340	     */
341	    private static String normalizeAddress(String value) {
342	        if (value == null) {
343	            return "";
344	        }
345	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
346	        if (collapsed.isEmpty()) {
347	            return "";
348	        }
349	        String[] tokens = collapsed.split(" ");
350	        StringBuilder sb = new StringBuilder(collapsed.length());
351	        for (int i = 0; i < tokens.length; i++) {
352	            if (i > 0) {
353	                sb.append(' ');
354	            }
355	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
356	        }
357	        return sb.toString();
358	    }
359	
360	    /**
361	     * Derive the stable household identifier shared by owners with the same normalized last name
362	     * and address. It is a deterministic function of those two values, so every member of a
363	     * household independently derives the same identifier: the first 12 upper-case hex characters
364	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
365	     */
366	    private static String householdId(String normalizedLastName, String normalizedAddress) {
367	        try {
368	            byte[] digest = MessageDigest.getInstance("SHA-256")
369	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
370	            StringBuilder sb = new StringBuilder(digest.length * 2);
371	            for (byte b : digest) {
372	                sb.append(String.format("%02x", b));
373	            }
374	            return sb.substring(0, 12).toUpperCase();
375	        }
376	        catch (NoSuchAlgorithmException e) {
377	            throw new IllegalStateException("SHA-256 not available", e);
378	        }
379	    }
380	
381	    /**
382	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
383	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
384	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
385	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
386	     */
387	    /**
388	     * Count the existing owners that share the given first and last name, compared
389	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
390	     * namesakes that already existed at creation time (the new owner itself is not included).
391	     */
392	    private int countNamesakes(String firstName, String lastName) {
393	        return (int) this.clinicService.findAllOwners().stream()
394	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
395	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
396	                && existing.getLastName().equalsIgnoreCase(lastName))
397	            .count();
398	    }
399	
400	    /**
401	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
402	     * request to create another owner in it is rejected as a conflict.
403	     */
404	    private static final int MAX_OWNERS_PER_CITY = 50;
405	
406	    /**
407	     * Count the existing owners registered in the given city, compared case-insensitively (as in
408	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
409	     * reflects the owners that already existed at creation time.
410	     */
411	    private int countOwnersInCity(String city) {
412	        return (int) this.clinicService.findAllOwners().stream()
413	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
414	            .count();
415	    }
416	
417	    /**
418	     * The maximum number of owners that may be created on a single day. Once this many owners
419	     * already carry a given day's registration date, a request to create another owner that day is
420	     * rejected with a 429.
421	     */
422	    private static final int MAX_OWNERS_PER_DAY = 100;
423	
424	    /**
425	     * Count the existing owners whose registration date is the given day. Called before the new
426	     * owner is saved, so the returned value reflects the owners that already existed at creation
427	     * time.
428	     */
429	    private int countOwnersRegisteredOn(LocalDate date) {
430	        return (int) this.clinicService.findAllOwners().stream()
431	            .filter(existing -> date.equals(existing.getRegistrationDate()))
432	            .count();
433	    }
434	
435	    private String nextCustomerCode(String city, String lastName) {
436	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
437	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
438	        long sequence = this.clinicService.findAllOwners().stream()
439	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
440	            .count() + 1L;
441	        return String.format("%s-%s-%04d", city3, last3, sequence);
442	    }
443	
444	    /**
445	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
446	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
447	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
448	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
449	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
450	     */
451	    private static String toE164(String raw) {
452	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
453	        boolean hasCountryCode = cleaned.startsWith("+");
454	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
455	        if (!digits.matches("\\d+")) {
456	            throw new InvalidOwnerFieldsException(List.of("telephone"));
457	        }
458	        if (!hasCountryCode) {
459	            if (digits.startsWith("0")) {
460	                digits = digits.substring(1);
461	            }
462	            digits = "61" + digits;
463	        }
464	        if (digits.length() < 8 || digits.length() > 15) {
465	            throw new InvalidOwnerFieldsException(List.of("telephone"));
466	        }
467	        return "+" + digits;
468	    }
469	
470	    /**
471	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
472	     * and a domain with at least one dot-separated label, none of which contain whitespace or
473	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
474	     */
475	    private static final Pattern EMAIL_PATTERN =
476	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
477	
478	    /**
479	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
480	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
481	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
482	     * 400. A valid address is returned lower-cased.
483	     */
484	    private static String normalizeEmail(String email) {
485	        if (email == null || email.isEmpty()) {
486	            return null;
487	        }
488	        String trimmed = email.trim();
489	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
490	            throw new InvalidOwnerFieldsException(List.of("email"));
491	        }
492	        return trimmed.toLowerCase();
493	    }
494	}
